import csv
import sqlite3
from typing import Optional

VALID_STAGES = ["lead", "qualified", "proposal", "won", "lost"]
STAGE_ORDER = {s: i for i, s in enumerate(VALID_STAGES)}
TERMINAL = {"won", "lost"}
STAGE_PROB = {
    "lead": 0.1,
    "qualified": 0.3,
    "proposal": 0.6,
    "won": 1.0,
    "lost": 0.0,
}


def get_connection(db_path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    return conn


def init_db(conn: sqlite3.Connection) -> None:
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS contacts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            name TEXT NOT NULL,
            company TEXT,
            phone TEXT
        );
        CREATE TABLE IF NOT EXISTS opportunities (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            contact_id INTEGER NOT NULL REFERENCES contacts(id),
            amount REAL NOT NULL,
            stage TEXT NOT NULL DEFAULT 'lead',
            close_date TEXT,
            FOREIGN KEY (contact_id) REFERENCES contacts(id)
        );
    """)


def add_contact(conn, email: str, name: str, company=None, phone=None) -> int:
    cur = conn.execute(
        "INSERT INTO contacts (email, name, company, phone) VALUES (?, ?, ?, ?)",
        (email.lower(), name, company, phone),
    )
    conn.commit()
    return cur.lastrowid


def list_contacts(conn, company=None):
    if company:
        rows = conn.execute(
            "SELECT * FROM contacts WHERE company = ?", (company,)
        ).fetchall()
    else:
        rows = conn.execute("SELECT * FROM contacts").fetchall()
    return [dict(r) for r in rows]


def get_contact_by_email(conn, email: str):
    row = conn.execute(
        "SELECT * FROM contacts WHERE email = ?", (email.lower(),)
    ).fetchone()
    return dict(row) if row else None


def get_contact_id(conn, email: str) -> Optional[int]:
    row = conn.execute(
        "SELECT id FROM contacts WHERE email = ?", (email.lower(),)
    ).fetchone()
    return row["id"] if row else None


def add_opp(conn, title: str, contact_id: int, amount: float, stage="lead", close_date=None) -> int:
    cur = conn.execute(
        "INSERT INTO opportunities (title, contact_id, amount, stage, close_date) VALUES (?, ?, ?, ?, ?)",
        (title, contact_id, amount, stage, close_date),
    )
    conn.commit()
    return cur.lastrowid


def list_opps(conn, stage=None, contact_email=None, sort=None):
    parts = ["SELECT o.*, c.email as contact_email FROM opportunities o JOIN contacts c ON o.contact_id = c.id"]
    conds = []
    params = []
    if stage:
        conds.append("o.stage = ?")
        params.append(stage)
    if contact_email:
        conds.append("c.email = ?")
        params.append(contact_email.lower())
    if conds:
        parts.append("WHERE " + " AND ".join(conds))
    if sort == "amount":
        parts.append("ORDER BY o.amount DESC")
    elif sort == "stage":
        parts.append("ORDER BY o.stage, o.title")
    else:
        parts.append("ORDER BY o.id")
    rows = conn.execute(" ".join(parts), params).fetchall()
    return [dict(r) for r in rows]


def get_opp(conn, opp_id: int):
    row = conn.execute(
        "SELECT o.*, c.email as contact_email FROM opportunities o JOIN contacts c ON o.contact_id = c.id WHERE o.id = ?",
        (opp_id,),
    ).fetchone()
    return dict(row) if row else None


def move_opp(conn, opp_id: int, new_stage: str) -> None:
    if new_stage not in VALID_STAGES:
        raise ValueError(f"Invalid stage: {new_stage}")
    opp = get_opp(conn, opp_id)
    if opp is None:
        raise ValueError(f"Opportunity {opp_id} not found")
    current_stage = opp["stage"]
    if current_stage in TERMINAL:
        raise ValueError(f"Cannot move from terminal stage '{current_stage}'")
    if STAGE_ORDER[new_stage] <= STAGE_ORDER[current_stage]:
        raise ValueError(
            f"Cannot move backward from '{current_stage}' to '{new_stage}'; advance only"
        )
    conn.execute(
        "UPDATE opportunities SET stage = ? WHERE id = ?",
        (new_stage, opp_id),
    )
    conn.commit()


def pipeline(conn):
    rows = conn.execute(
        "SELECT stage, COUNT(*) as count, SUM(amount) as total FROM opportunities GROUP BY stage ORDER BY stage"
    ).fetchall()
    return [dict(r) for r in rows]


def won_report(conn, from_date: str, to_date: str) -> float:
    row = conn.execute(
        "SELECT COALESCE(SUM(amount), 0) as total FROM opportunities WHERE stage = 'won' AND close_date >= ? AND close_date <= ?",
        (from_date, to_date),
    ).fetchone()
    return row["total"]


def forecast(conn) -> float:
    rows = conn.execute(
        "SELECT stage, SUM(amount) as total FROM opportunities GROUP BY stage"
    ).fetchall()
    total = 0.0
    for r in rows:
        total += r["total"] * STAGE_PROB.get(r["stage"], 0)
    return total


def export_opps_csv(conn, file_path: str) -> None:
    contacts = conn.execute("SELECT * FROM contacts").fetchall()
    opps = conn.execute(
        "SELECT o.*, c.email as contact_email FROM opportunities o JOIN contacts c ON o.contact_id = c.id"
    ).fetchall()
    with open(file_path, "w", newline="") as f:
        cw = csv.writer(f)
        cw.writerow(["section"])
        cw.writerow(["contacts"])
        cw.writerows([[r["id"], r["email"], r["name"], r["company"], r["phone"]] for r in contacts])
        cw.writerow(["opportunities"])
        cw.writerows(
            [[r["id"], r["title"], r["contact_email"], r["amount"], r["stage"], r["close_date"]] for r in opps]
        )


